//! 🧰️ Kit types, designs, placed pieces, connections, typed child handles and history pins.
use crate::standards::v1::subsets::base::schema::snapshot::sqlite::native::Bound;
use semio_framework_os_kernel::sqlite_snapshot::artifact::{FloatColumn,FloatRow as SqliteRow,insert_ieee754,insert_key_ieee754};
use super::{SemioKitSnapshot,SemioKitType,SemioKitDesign,SemioKitPiece,SemioKitConnection,SemioTransform,SemioObjectSnapshot,SemioModelSnapshot,SemioValueSnapshot};
use crate::standards::v1::subsets::base::schema::{geometry::{SemioPoint3,SemioQuaternion},child::validate_semio_child_identity};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,reconstruct_text},validate_sqlite_database_schema,SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase}};
use std::collections::{BTreeMap,BTreeSet};
fn number(value:usize)->Result<i64,String>{i64::try_from(value).map_err(|error|error.to_string())}
fn identity<'a>(row:impl std::borrow::Borrow<SqliteRow<'a>>,columns:usize)->Result<(),String>{let row=*row.borrow();if row.rowid<=0||row.integer(0)?!=row.rowid||row.values.len()!=columns{Err("invalid Semio kit row identity or columns".into())}else{Ok(())}}
fn ordered<'a>(mut rows:Vec<SqliteRow<'a>>)->Result<Vec<SqliteRow<'a>>,String>{rows.sort_by_key(|row|row.integer(2).unwrap_or(-1));for(ordinal,row)in rows.iter().enumerate(){if row.integer(2)?!=number(ordinal)?{return Err("Semio kit ordinals must be contiguous".into());}}Ok(rows)}
fn reference(target:&store::os_io::ArtifactRef,p:&mut Projection<'_,'_>)->Result<i64,String>{let id=p.insert_float("semio_kit_reference",&[Cell::Text(&target.artifact_id),Cell::Text(&target.dialect.artifact_kind),Cell::Text(&target.dialect.standard),Cell::Text(&target.dialect.subset)])?;p.checkpoint()?;Ok(id)}
fn project_children<S>(children:&[store::ArtifactChild<S>],table:&str,subset:&str,p:&mut Projection<'_,'_>)->Result<(),String>{let mut ids=BTreeSet::new();for(ordinal,child)in children.iter().enumerate(){let target=reference(&child.target,p)?;p.insert_float(table,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&child.child_id),Cell::Integer(target)])?;if !ids.insert(child.child_id.as_str()){return Err("duplicate Semio kit child identifier".into());}validate_semio_child_identity(&child.child_id,&child.target,subset)?;}Ok(())}
fn children<S>(database:&SqliteDatabase,table:&str,subset:&str,references:&mut BTreeMap<i64,store::os_io::ArtifactRef>,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<store::ArtifactChild<S>>,String>{let mut result=Vec::new();let mut ids=BTreeSet::new();let mut child_ids=BTreeSet::new();for(count,row)in ordered_float_rows(database,table,2,control)?.into_iter().enumerate(){identity(row,5)?;if row.integer(1)?!=1||!ids.insert(row.rowid)||!child_ids.insert(row.text(3)?){return Err("invalid Semio kit child ownership or identity".into());}if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}let target=references.remove(&row.integer(4)?).ok_or("dangling or multiply owned Semio kit child reference")?;validate_semio_child_identity(row.text(3)?,&target,subset)?;result.push(store::ArtifactChild::new(reconstruct_text(control,row.text(3)?)?,target));}Ok(result)}
impl ArtifactSqliteSnapshot for SemioKitSnapshot{
fn encode_sqlite_snapshot_native(&self,encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,String>{super::native_encoding::encode(self,encoding,control)}
fn decode_sqlite_snapshot_native(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{super::native_decoding::decode(payload,control)}
fn preflight_sqlite_snapshot_encoding(&self,_encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=Bound::new("",control)?;self.native_fields(&mut b)?;b.finish()}

fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;
if dialect.artifact_kind!="s.stdio.semio"||dialect.standard!="v1"||(dialect.subset!="*"&&dialect.subset!="kit"){return Err(String::from("Semio owned snapshot dialect differs from its dedicated semantic subset").into());}
let row=database.table("semio_kit_document")?.single_row()?;
if row.rowid!=1||row.integer(0)?!=1||row.text(1)?!=self.schema{return Err(String::from("Semio owned document identity differs from projected semantic fields").into());}
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}

const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert_key_float("semio_kit_document",1,&[Cell::Text(&self.schema)])?;let mut types=BTreeMap::new();for(ordinal,kind)in self.types.iter().enumerate(){let id=p.insert_float("semio_kit_type",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&kind.id),Cell::Text(&kind.name),Cell::Text(&kind.category)])?;if types.insert(kind.id.as_str(),id).is_some(){return Err("duplicate Semio kit type identifier".into());}}
let mut design_ids=BTreeSet::new();for(ordinal,design)in self.designs.iter().enumerate(){let design_id=p.insert_float("semio_kit_design",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&design.id),Cell::Text(&design.name)])?;if !design_ids.insert(design.id.as_str()){return Err("duplicate Semio kit design identifier".into());}let mut pieces=BTreeMap::new();for(ordinal,piece)in design.pieces.iter().enumerate(){let t=piece.transform;let id=p.insert_float("semio_kit_piece",&[Cell::Integer(design_id),Cell::Integer(number(ordinal)?),Cell::Text(&piece.id),Cell::Integer(*types.get(piece.type_id.as_str()).ok_or("dangling Semio kit piece type")?),Cell::Real(t.translation.x),Cell::Real(t.translation.y),Cell::Real(t.translation.z),Cell::Real(t.rotation.x),Cell::Real(t.rotation.y),Cell::Real(t.rotation.z),Cell::Real(t.rotation.w),Cell::Real(t.scale.x),Cell::Real(t.scale.y),Cell::Real(t.scale.z)])?;if pieces.insert(piece.id.as_str(),id).is_some(){return Err("duplicate Semio kit piece identifier".into());}}
let mut ids=BTreeSet::new();for(ordinal,connection)in design.connections.iter().enumerate(){if !ids.insert(connection.id.as_str()){return Err("duplicate Semio kit connection identifier".into());}p.insert_float("semio_kit_connection",&[Cell::Integer(design_id),Cell::Integer(number(ordinal)?),Cell::Text(&connection.id),Cell::Integer(*pieces.get(connection.connecting_piece_id.as_str()).ok_or("dangling Semio kit connecting piece")?),Cell::Text(&connection.connecting_port),Cell::Integer(*pieces.get(connection.connected_piece_id.as_str()).ok_or("dangling Semio kit connected piece")?),Cell::Text(&connection.connected_port)])?;}}
project_children(&self.objects,"semio_kit_object_child","object",&mut p)?;project_children(&self.models,"semio_kit_model_child","model",&mut p)?;if let Some(child)=&self.properties{let target=reference(&child.target,&mut p)?;p.insert_float("semio_kit_value_child",&[Cell::Integer(1),Cell::Text(&child.child_id),Cell::Integer(target)])?;validate_semio_child_identity(&child.child_id,&child.target,"value")?;}
for(ordinal,link)in self.representations.iter().enumerate(){let target=reference(&link.target,&mut p)?;let(kind,checkpoint,blob)=match &link.pin{store::LinkPin::Head=>("head",Cell::Null,Cell::Null),store::LinkPin::Checkpoint{id}=>("checkpoint",Cell::Text(id),Cell::Null),store::LinkPin::Snapshot{blob}=>{let id=p.insert_float("semio_kit_blob",&[Cell::Text(&blob.hash),Cell::Text(&blob.size.to_string()),Cell::Text(&blob.media_type)])?;("snapshot",Cell::Null,Cell::Integer(id))}};p.insert_float("semio_kit_representation",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Integer(*types.get(link.role.as_str()).ok_or("dangling Semio kit representation type role")?),Cell::Integer(target),Cell::Text(kind),checkpoint,blob])?;}p.finish()
}
fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String> { Self::reconstruct_sqlite_database(database, control, Self::SQLITE_SCHEMA) }
}

impl SemioKitSnapshot {
    /// 🧩️ Restores the owned typed subset inside its independently declared relational composition.
    pub fn reconstruct_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>, declared_schema: &str)->Result<Self,String> {

control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,declared_schema,control.limits()).map_err(|error|error.to_string())?;let document=single_float_row(database,"semio_kit_document")?;identity(document,2)?;if document.rowid!=1{return Err("invalid Semio kit document identifier".into());}
let mut types=Vec::new();let mut type_names=BTreeMap::new();let mut native_ids=BTreeSet::new();for row in ordered_float_rows(database,"semio_kit_type",2,control)?{identity(row,6)?;if row.integer(1)?!=1||type_names.insert(row.rowid,row.text(3)?).is_some()||!native_ids.insert(row.text(3)?){return Err("invalid Semio kit type ownership or identity".into());}types.push(SemioKitType{id:reconstruct_text(control,row.text(3)?)?,name:reconstruct_text(control,row.text(4)?)?,category:reconstruct_text(control,row.text(5)?)?});}
let design_rows=ordered_float_rows(database,"semio_kit_design",2,control)?;let mut design_ids=BTreeSet::new();let mut native_ids=BTreeSet::new();for row in &design_rows{identity(row,5)?;if row.integer(1)?!=1||!design_ids.insert(row.rowid)||!native_ids.insert(row.text(3)?){return Err("invalid Semio kit design ownership or identity".into());}}
let mut pieces=BTreeMap::<i64,Vec<SqliteRow<'_>>>::new();let mut piece_names=BTreeMap::new();let mut ids=BTreeSet::new();let mut completed=0usize;for row in float_rows(database,"semio_kit_piece",control)?{identity(row,15)?;if !design_ids.contains(&row.integer(1)?)||!ids.insert(row.rowid){return Err("invalid Semio kit piece ownership or identity".into());}row.integer(2)?;piece_names.insert(row.rowid,(row.integer(1)?,row.text(3)?));pieces.entry(row.integer(1)?).or_default().push(row);completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}
let mut connections=BTreeMap::<i64,Vec<SqliteRow<'_>>>::new();let mut ids=BTreeSet::new();for row in float_rows(database,"semio_kit_connection",control)?{identity(row,8)?;if !design_ids.contains(&row.integer(1)?)||!ids.insert(row.rowid){return Err("invalid Semio kit connection ownership or identity".into());}row.integer(2)?;connections.entry(row.integer(1)?).or_default().push(row);completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}
let mut designs=Vec::new();for design in design_rows{let mut native_pieces=Vec::new();let mut native_ids=BTreeSet::new();for row in ordered(pieces.remove(&design.rowid).unwrap_or_default())?{if !native_ids.insert(row.text(3)?){return Err("duplicate Semio kit piece native identifier".into());}let transform=SemioTransform{translation:SemioPoint3{x:row.real(5)?,y:row.real(6)?,z:row.real(7)?},rotation:SemioQuaternion{x:row.real(8)?,y:row.real(9)?,z:row.real(10)?,w:row.real(11)?},scale:SemioPoint3{x:row.real(12)?,y:row.real(13)?,z:row.real(14)?}};native_pieces.push(SemioKitPiece{id:reconstruct_text(control,row.text(3)?)?,type_id:reconstruct_text(control,type_names.get(&row.integer(4)?).ok_or("dangling Semio kit piece type")?)?,transform});completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}
let mut native_connections=Vec::new();let mut native_ids=BTreeSet::new();for row in ordered(connections.remove(&design.rowid).unwrap_or_default())?{if !native_ids.insert(row.text(3)?){return Err("duplicate Semio kit connection native identifier".into());}let connecting=piece_names.get(&row.integer(4)?).ok_or("dangling Semio kit connecting piece")?;let connected=piece_names.get(&row.integer(6)?).ok_or("dangling Semio kit connected piece")?;if connecting.0!=design.rowid||connected.0!=design.rowid{return Err("Semio kit connection crosses its owning design".into());}native_connections.push(SemioKitConnection{id:reconstruct_text(control,row.text(3)?)?,connecting_piece_id:reconstruct_text(control,connecting.1)?,connecting_port:reconstruct_text(control,row.text(5)?)?,connected_piece_id:reconstruct_text(control,connected.1)?,connected_port:reconstruct_text(control,row.text(7)?)?});completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}designs.push(SemioKitDesign{id:reconstruct_text(control,design.text(3)?)?,name:reconstruct_text(control,design.text(4)?)?,pieces:native_pieces,connections:native_connections});}
let mut references=BTreeMap::new();for row in float_rows(database,"semio_kit_reference",control)?{identity(row,5)?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;let target=store::os_io::ArtifactRef{artifact_id:reconstruct_text(control,row.text(1)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:reconstruct_text(control,row.text(2)?)?,standard:reconstruct_text(control,row.text(3)?)?,subset:reconstruct_text(control,row.text(4)?)?}};if references.insert(row.rowid,target).is_some(){return Err("invalid or duplicate Semio kit reference".into());}completed+=1;}
let objects=children::<SemioObjectSnapshot>(database,"semio_kit_object_child","object",&mut references,control)?;let models=children::<SemioModelSnapshot>(database,"semio_kit_model_child","model",&mut references,control)?;let table=database.table("semio_kit_value_child")?;let properties=if table.rows.is_empty(){None}else{let row=SqliteRow::new(table.single_row()?,float_columns("semio_kit_value_child"))?;identity(row,4)?;if row.integer(1)?!=1{return Err("invalid Semio kit value child owner".into());}let target=references.remove(&row.integer(3)?).ok_or("dangling Semio kit value child reference")?;validate_semio_child_identity(row.text(2)?,&target,"value")?;Some(store::ArtifactChild::<SemioValueSnapshot>::new(reconstruct_text(control,row.text(2)?)?,target))};
let mut blobs=BTreeMap::new();for row in float_rows(database,"semio_kit_blob",control)?{identity(row,4)?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;let size=row.text(2)?.parse::<u64>().map_err(|error|error.to_string())?;if size.to_string()!=row.text(2)?||blobs.insert(row.rowid,store::BlobRef{hash:reconstruct_text(control,row.text(1)?)?,size,media_type:reconstruct_text(control,row.text(3)?)?}).is_some(){return Err("invalid Semio kit blob identity or size".into());}completed+=1;}
let mut representations=Vec::new();let mut ids=BTreeSet::new();for row in ordered_float_rows(database,"semio_kit_representation",2,control)?{identity(row,8)?;if row.integer(1)?!=1||!ids.insert(row.rowid){return Err("invalid Semio kit representation ownership or identity".into());}let checkpoint=row.optional_text(6)?;let blob=if row.is_null(7)?{None}else{Some(row.integer(7)?)};let pin=match row.text(5)?{"head" if checkpoint.is_none()&&blob.is_none()=>store::LinkPin::Head,"checkpoint" if blob.is_none()=>store::LinkPin::Checkpoint{id:reconstruct_text(control,checkpoint.ok_or("missing Semio kit checkpoint pin")?)?},"snapshot" if checkpoint.is_none()=>store::LinkPin::Snapshot{blob:blobs.remove(&blob.ok_or("missing Semio kit snapshot pin")?).ok_or("dangling or multiply owned Semio kit blob pin")?},_=>return Err("invalid Semio kit link pin shape".into())};representations.push(store::ArtifactLink{target:references.remove(&row.integer(4)?).ok_or("dangling or multiply owned Semio kit representation reference")?,role:reconstruct_text(control,type_names.get(&row.integer(3)?).ok_or("dangling Semio kit representation type role")?)?,pin});completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}
if !references.is_empty()||!blobs.is_empty(){return Err("orphan Semio kit reference or blob pin descriptor".into());}control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,completed)?;Ok(Self{schema:reconstruct_text(control,document.text(1)?)?,types,designs,objects,models,properties,representations})
    }
}

fn float_columns(table:&str)->&'static [FloatColumn]{match table{"semio_kit_piece"=>&[FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12),FloatColumn::Binary64(13),FloatColumn::Binary64(14)],_=>&[]}}
trait FloatProjection { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>; fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>; }
impl FloatProjection for Projection<'_,'_> { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>{insert_ieee754(self,table,cells,float_columns(table))} fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>{insert_key_ieee754(self,table,key,cells,float_columns(table))} }
fn float_rows<'a>(db:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let table_rows=db.table(table)?;control.check_rows(table_rows.rows.len())?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,table_rows.rows.len())?;let mut result=Vec::new();for(count,row)in table_rows.rows.iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,table_rows.rows.len())?;}}Ok(result)}
fn ordered_float_rows<'a>(db:&'a SqliteDatabase,table:&str,ordinal:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let mut result=Vec::new();for(count,row)in semio_framework_os_kernel::sqlite_snapshot::artifact::ordered_row_refs(db.table(table)?,ordinal,control)?.into_iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn single_float_row<'a>(db:&'a SqliteDatabase,table:&str)->Result<SqliteRow<'a>,String>{SqliteRow::new(db.table(table)?.single_row()?,float_columns(table))}

impl SemioKitSnapshot{
/// 📏️ Bounds explicitly owned native fields before encoding.
pub fn native_fields(&self,b:&mut Bound<'_,'_>)->Result<(),String>{b.text(&self.schema)?;b.entities(self.types.len())?;for ty in &self.types{b.text(&ty.id)?;b.text(&ty.name)?;b.text(&ty.category)?;}b.entities(self.designs.len())?;for design in &self.designs{b.text(&design.id)?;b.text(&design.name)?;b.entities(design.pieces.len())?;for piece in &design.pieces{b.text(&piece.id)?;b.text(&piece.type_id)?;b.scalars(10)?;}b.entities(design.connections.len())?;for connection in &design.connections{b.text(&connection.id)?;b.text(&connection.connecting_piece_id)?;b.text(&connection.connecting_port)?;b.text(&connection.connected_piece_id)?;b.text(&connection.connected_port)?;}}for child in &self.objects{crate::standards::v1::subsets::object::schema::snapshot::sqlite::native_child(child,b)?;}for child in &self.models{crate::standards::v1::subsets::object::schema::snapshot::sqlite::native_child(child,b)?;}if let Some(child)=&self.properties{crate::standards::v1::subsets::object::schema::snapshot::sqlite::native_child(child,b)?;}b.entities(self.representations.len())?;for link in &self.representations{b.text(&link.role)?;crate::standards::v1::subsets::object::schema::snapshot::sqlite::native_reference(&link.target,b)?;match &link.pin{store::LinkPin::Head=>{},store::LinkPin::Checkpoint{id}=>b.text(id)?,store::LinkPin::Snapshot{blob}=>{b.text(&blob.hash)?;b.text(&blob.media_type)?;b.scalars(1)?;}}}Ok(())}
}
